import Header from './components/Header';
import './styles/main.css';
import { BrowserRouter, Routes, Route, useLocation } from "react-router-dom";

const App = () => {
    return (
        <BrowserRouter>
            <Header />
            <Route path="/" element={<Header />} >
            </Route>
        </BrowserRouter>
    );
};

export default App;
